<?php
declare(strict_types=1);
require_once __DIR__ . '/../idempotency.php'; require_once __DIR__ . '/audit_service.php'; require_once __DIR__ . '/notification_service.php'; require_once __DIR__ . '/../repositories/support_repository.php';
function support_result(bool $ok,int $status,string $message,array $data=[]):array{$r=['ok'=>$ok,'status'=>$status,'message'=>$message];if($data!==[])$r['data']=$data;return$r;}
function support_existing_user(mysqli $conn,int $userId):bool{return support_repository_one($conn,'SELECT id FROM users WHERE id=?','i',[$userId])!==[];}
function support_open_case(mysqli $conn,int $actorId,string $role,int $orderId,?int $deliveryId,string $caseType,string $subject,string $message,string $key):array{if(!in_array($role,['customer','restaurant','driver'],true)||$orderId<=0||trim($message)==='')return support_result(false,422,'A valid role, order and message are required.');$scope=support_repository_order_scope($conn,$orderId);if($scope===[])return support_result(false,404,'Order not found.');$owner=($role==='customer'&&(int)$scope['customer_user_id']===$actorId)||($role==='restaurant'&&(int)$scope['owner_user_id']===$actorId)||($role==='driver'&&(int)($scope['driver_user_id']??0)===$actorId&&in_array((string)($scope['delivery_status']??''),['assigned','arrived','picked_up'],true));if(!$owner)return support_result(false,403,'You do not own this order context.');$hash=savora_idempotency_hash('support_open_case',['orderId'=>$orderId,'role'=>$role,'subject'=>$subject,'message'=>$message]);$conn->begin_transaction();try{$stored=savora_idempotency_find($conn,$actorId,$key,'support_open_case',$hash);if($stored!==null){$conn->commit();return$stored;}$reference='CASE-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(4)));$subject=mb_substr(trim($subject),0,200);$case=$conn->prepare("INSERT INTO support_cases(reference_code,order_id,case_type,reporting_role,reporting_user_id,priority,status,subject,sla_due_at) VALUES(?,?,?,?,?,'medium','open',?,DATE_ADD(NOW(),INTERVAL 24 HOUR))");$case->bind_param('sissis',$reference,$orderId,$caseType,$role,$actorId,$subject);$case->execute();$caseId=(int)$case->insert_id;$case->close();$msg=$conn->prepare('INSERT INTO case_messages(case_id,author_role,author_user_id,message,internal_only) VALUES(?,?,?,?,0)');$msg->bind_param('isis',$caseId,$role,$actorId,$message);$msg->execute();$msg->close();$recipients=array_filter([$scope['customer_user_id'],$scope['owner_user_id'],$scope['driver_user_id']??0],static fn($id)=>(int)$id!==$actorId);foreach(array_unique(array_map('intval',$recipients)) as $recipient)if(support_existing_user($conn,$recipient))notification_queue($conn,$recipient,'support_case_opened','Support case opened','A support case was opened for order '.$scope['reference_code'].'.','support_case',$caseId);audit_append($conn,$actorId,'support_open_case','support_case',$caseId,null,['referenceCode'=>$reference],$subject,'SUP-'.$caseId);$response=support_result(true,201,'Support case opened.',['caseId'=>$caseId,'referenceCode'=>$reference,'version'=>1]);savora_idempotency_store($conn,$actorId,$key,'support_open_case',$hash,$response);$conn->commit();return$response;}catch(Throwable$e){$conn->rollback();return support_result(false,409,$e->getMessage());}}
function support_add_message(mysqli $conn,int $actorId,string $role,int $caseId,string $message,int $expectedVersion,string $key):array{$case=support_repository_case($conn,$caseId);if($case===[])return support_result(false,404,'Support case not found.');$allowed=($role==='admin')||((int)$case['reporting_user_id']===$actorId&&(string)$case['reporting_role']===$role);if(!$allowed)return support_result(false,403,'You cannot add a message to this case.');$hash=savora_idempotency_hash('support_add_message',['caseId'=>$caseId,'message'=>$message,'version'=>$expectedVersion]);$conn->begin_transaction();try{$stored=savora_idempotency_find($conn,$actorId,$key,'support_add_message',$hash);if($stored!==null){$conn->commit();return$stored;}$lock=support_repository_case($conn,$caseId,true);if((int)$lock['version']!==$expectedVersion)throw new RuntimeException('Case is stale.');$msg=$conn->prepare('INSERT INTO case_messages(case_id,author_role,author_user_id,message,internal_only) VALUES(?,?,?, ?,0)');$msg->bind_param('isis',$caseId,$role,$actorId,$message);$msg->execute();$msg->close();$update=$conn->prepare('UPDATE support_cases SET version=version+1 WHERE id=? AND version=?');$update->bind_param('ii',$caseId,$expectedVersion);$update->execute();if($update->affected_rows!==1)throw new RuntimeException('Case changed.');$update->close();$response=support_result(true,200,'Support message added.',['caseId'=>$caseId,'version'=>$expectedVersion+1]);savora_idempotency_store($conn,$actorId,$key,'support_add_message',$hash,$response);$conn->commit();return$response;}catch(Throwable$e){$conn->rollback();return support_result(false,409,$e->getMessage());}}
function support_resolve_case(mysqli $conn,int $actorId,int $caseId,string $resolution,int $expectedVersion,string $key):array{$case=support_repository_case($conn,$caseId);if($case===[])return support_result(false,404,'Support case not found.');$row=$conn->query('SELECT role FROM users WHERE id='.(int)$actorId)->fetch_assoc();if(($row['role']??'')!=='admin')return support_result(false,403,'Only Admin can resolve a support case.');$hash=savora_idempotency_hash('support_resolve_case',['caseId'=>$caseId,'resolution'=>$resolution,'version'=>$expectedVersion]);$conn->begin_transaction();try{$stored=savora_idempotency_find($conn,$actorId,$key,'support_resolve_case',$hash);if($stored!==null){$conn->commit();return$stored;}$update=$conn->prepare("UPDATE support_cases SET status='resolved',resolution=?,version=version+1 WHERE id=? AND version=? AND status NOT IN ('resolved','closed')");$update->bind_param('sii',$resolution,$caseId,$expectedVersion);$update->execute();if($update->affected_rows!==1)throw new RuntimeException('Case is stale or already resolved.');$update->close();$response=support_result(true,200,'Support case resolved.',['caseId'=>$caseId,'version'=>$expectedVersion+1,'status'=>'resolved']);savora_idempotency_store($conn,$actorId,$key,'support_resolve_case',$hash,$response);$conn->commit();return$response;}catch(Throwable$e){$conn->rollback();return support_result(false,409,$e->getMessage());}}
